function sf_distribution_release_rows(): array {
    $path=SF_ROOT.'/data/releases.json';
    $rows=is_file($path)?json_decode((string)file_get_contents($path),true):[];
    return is_array($rows)?array_values($rows):[];
}
function sf_distribution_release(string $releaseId): ?array {
    foreach(sf_distribution_release_rows() as $r) if((string)($r['id']??'')===$releaseId) return $r;
    return null;
}
function sf_distribution_track(string $trackId): ?array {
    foreach(sf_catalog() as $t) if((string)($t['id']??'')===$trackId) return $t;
    return null;
}
function sf_distribution_normalize_isrc(string $v): string { return strtoupper(preg_replace('/[^A-Z0-9]/i','',$v)??''); }
function sf_distribution_valid_isrc(string $v): bool { $v=sf_distribution_normalize_isrc($v); return (bool)preg_match('/^[A-Z]{2}[A-Z0-9]{3}[0-9]{7}$/',$v); }
function sf_distribution_normalize_barcode(string $v): string { return preg_replace('/\D/','',$v)??''; }
function sf_distribution_valid_barcode(string $v): bool {
    $d=sf_distribution_normalize_barcode($v);$n=strlen($d);if(!in_array($n,[12,13],true))return false;
    $sum=0;$weight=3;for($i=$n-2;$i>=0;$i--){$sum+=((int)$d[$i])*$weight;$weight=$weight===3?1:3;}
    return ((10-($sum%10))%10)===(int)$d[$n-1];
}
function sf_distribution_destinations(): array { return ['spotify','apple_music','youtube_music','amazon_music','bandcamp']; }
function sf_distribution_valid_https_url(string $v): bool {
    if($v==='')return true;$p=parse_url($v);return is_array($p)&&strtolower((string)($p['scheme']??''))==='https'&&trim((string)($p['host']??''))!==''&&(bool)filter_var($v,FILTER_VALIDATE_URL);
}
function sf_distribution_transition_allowed(string $from,string $to): bool {
    if($from===$to)return true;
    $map=[
      'draft'=>['preparing','archived'],
      'preparing'=>['draft','ready','archived'],
      'ready'=>['preparing','submitted','archived'],
      'submitted'=>['scheduled','archived'],
      'scheduled'=>['live','archived'],
      'live'=>['archived'],
      'archived'=>[]
    ];
    return in_array($to,$map[$from]??[],true);
}
function sf_distribution_storage_key(string $releaseId): string {
    $k=preg_replace('/[^a-z0-9-]+/i','-',trim($releaseId))??'';$k=trim(strtolower($k),'-');if($k==='')throw new InvalidArgumentException('Release storage key is invalid.');return substr($k,0,80);
}
function sf_distribution_managed_media_path(array $asset): ?string {
    $rel=ltrim((string)($asset['stored_path']??''),'/');if($rel===''||!str_starts_with($rel,'storage/media/'))return null;$root=realpath(SF_ROOT.'/storage/media');$abs=realpath(SF_ROOT.'/'.$rel);if(!$root||!$abs||!str_starts_with($abs,$root.DIRECTORY_SEPARATOR)||!is_file($abs))return null;return $abs;
}
function sf_distribution_destination_transition_allowed(string $from,string $to): bool {
    if($from===$to)return true;if($to==='failed')return true;if($from==='live')return false;if($from==='failed')return in_array($to,['preparing','submitted'],true);
    $rank=['not_started'=>0,'preparing'=>1,'submitted'=>2,'scheduled'=>3,'live'=>4];return isset($rank[$from],$rank[$to])&&$rank[$to]>=$rank[$from];
