    $now=gmdate('c');$year=(int)substr((string)($release['release_date']??gmdate('Y')),0,4);if($year<1900||$year>2100)$year=(int)gmdate('Y');
    $label=sf_clean_text($release['label']??'',180);$genre=sf_clean_text($release['genre']??'',100);$upc=sf_distribution_normalize_barcode((string)($release['upc_ean']??''));$catalog=sf_clean_text($release['catalog_number']??'',100);$tx=false;
    try{if(!$pdo->inTransaction()){$pdo->beginTransaction();$tx=true;}$q=$pdo->prepare("INSERT INTO distribution_releases(release_id,distribution_state,primary_artist,version_title,label,genre,subgenre,language,explicit,territory,copyright_line,phonographic_line,upc_ean,catalog_number,metadata_json,created_at,updated_at) VALUES(?,'draft','Stonefellow','',?,?,'','English',0,'worldwide',?,?,?,?,'{}',?,?)");$q->execute([$id,$label,$genre,'© '.$year.' '.($label?:'Stonefellow'),'℗ '.$year.' '.($label?:'Stonefellow'),$upc,$catalog,$now,$now]);
      foreach(sf_distribution_destinations() as $provider){$st=$pdo->prepare("INSERT INTO distribution_destinations(release_id,provider,status,external_id,release_url,notes,created_at,updated_at) VALUES(?,?,'not_started','','','',?,?)");$st->execute([$id,$provider,$now,$now]);}
