    foreach($entities as [$type,$id]){$q=$pdo->prepare('SELECT MAX(updated_at) FROM media_links WHERE entity_type=? AND entity_id=?');$q->execute([$type,$id]);$v=(string)($q->fetchColumn()?:'');if($v!==''&&strcmp($v,$latest)>0)$latest=$v;}
